std::vector<std::jthread> workers;
for (int i = 0; i < n; ++i)
  workers.emplace_back([&](std::stop_token st) {
    while (!st.stop_requested()) {
      std::unique_lock lk(m);
      cv.wait(lk, st, [&] { return !q.empty(); });
      if (q.empty()) return;                 // stop requested
      Job j = std::move(q.front()); q.pop(); lk.unlock();
      process(j); ack(j);
    }
  });

